# pod_ruleown_gate.sh : generated by mk_pod_ruleown.py. Runs ON THE POD (bash -s). Dry gates only (one selfcheck per arm), trains nothing.
set -u
W=/workspace/v8proof; cd $W/chain2 || exit 1
n=$(nvidia-smi --query-compute-apps=pid --format=csv,noheader 2>/dev/null | grep -c .); [ "${n:-0}" -lt 3 ] || { echo "REFUSED: $n GPU jobs running, a dry gate would be the fourth"; exit 1; }
a=$(grep -E '^anon ' /sys/fs/cgroup/memory.stat | cut -d' ' -f2); m=$(cat /sys/fs/cgroup/memory.max); [ $((m - a)) -gt 20000000000 ] || { echo 'REFUSED: less than 20 GB of the memory limit free'; exit 1; }
bash dry_gate.sh arms_ruleown_a.txt GOW_s0 PREREG_V8F_PROOF_ADD34 > $W/chains/ruleown_dry_GOW_s0.out 2>&1; echo "dry gate GOW_s0 rc $?"; tail -n 5 $W/chains/ruleown_dry_GOW_s0.out | cut -c1-300
bash dry_gate.sh arms_ruleown_a.txt GOW4_s0 PREREG_V8F_PROOF_ADD34 > $W/chains/ruleown_dry_GOW4_s0.out 2>&1; echo "dry gate GOW4_s0 rc $?"; tail -n 5 $W/chains/ruleown_dry_GOW4_s0.out | cut -c1-300
bash dry_gate.sh arms_ruledose2_a.txt GRW6_s0 PREREG_V8F_PROOF_ADD32 > $W/chains/ruleown_dry_GRW6_s0.out 2>&1; echo "dry gate GRW6_s0 rc $?"; tail -n 5 $W/chains/ruleown_dry_GRW6_s0.out | cut -c1-300
SC=$W/runs/motion_dry/GOW_s0/out/selfcheck.json; GA=$W/chains/ruleown_dry_gate_argv.txt
C2_CARD=PREREG_V8F_PROOF_ADD34 bash chain_arms.sh dryrun_GOW_s0 arms_ruleown_a.txt --dry-run | grep '^TRAIN GOW_s0: ' | sed 's|^TRAIN GOW_s0: ||' | tr ' ' '\n' | tail -n +3 > $GA; echo --selfcheck-only >> $GA
$W/../venv/bin/python gate_token3.py make --selfcheck $SC --argv-file $GA --out $W/chains/ruleown_dry_token_ft.json --kind HIERFT --commit dry --commit-verified false | tail -n 1 | cut -c1-200; echo "token kind HIERFT rc ${PIPESTATUS[0]} (must be 0)"
$W/../venv/bin/python gate_token3.py make --selfcheck $SC --argv-file $GA --out $W/chains/ruleown_dry_token_full.json --kind HIER --commit dry --commit-verified false | tail -n 1 | cut -c1-200; echo "token kind HIER rc ${PIPESTATUS[0]} (must be 1)"
$W/../venv/bin/python - <<'PYEOF'
import json
for a in ('GOW_s0', 'GOW4_s0', 'GRW6_s0'):
    try:
        s = json.load(open('/workspace/v8proof/runs/motion_dry/%s/out/selfcheck.json' % a)); i = s.get('info', {}); lv = s.get('levers', {})
        print('SELFCHECK', a, 'dvb', s.get('declared_vs_built'), 'live', (s.get('live') or {}).get('pass'), 'steps_total', s.get('steps_total'), 'init_applied', (lv.get('init_ckpt') or {}).get('applied'), 'w_rule_own', lv.get('w_rule_own'), 'rule_relabel', lv.get('rule_relabel'), 'rule_relabel_weight', lv.get('rule_relabel_weight'))
        print('   own probe', json.dumps(s.get('rule_own_probe'))[:700])
        print('   relabel probe', json.dumps(s.get('rule_relabel_probe'))[:300], '| info', json.dumps({k: v for k, v in i.items() if 'rule' in k and not isinstance(v, dict)})[:300])
        lt = (s.get('live') or {})
        print('   live keys', sorted(k for k in lt if 'loss' in k or 'rule' in k or 'term' in k)[:20], json.dumps({k: lt[k] for k in lt if ('loss' in k or 'rule' in k) and isinstance(lt[k], (int, float))})[:400])
    except Exception as e:
        print('SELFCHECK', a, 'ERR', e)
PYEOF
